
/* V3.3.6 F03 user-supplied GeoJSON, separate from pig farm records.
   Offline content is NOT an authoritative verification of species or operating status. */
window.F03Local = (() => {
 'use strict';
 const DB_NAME='pig-f03-geojson-v333', STORE='datasets',MAX_BYTES=60*1024*1024,MAX_ITEMS=100000,MAX_VERTICES=3200000;
 const datasets=new Map(),META=new Map(),packaged=new Map(), BUCKET=.025;
 let dbPromise=null;
 function safeInt(v){return Number.isSafeInteger(v)&&v>=0;}
 function hashText(s){let h=2166136261>>>0;const step=1;
  for(let i=0;i<s.length;i+=step){h=Math.imul((h^s.charCodeAt(i))>>>0,16777619)>>>0;}h=Math.imul(h^s.length,16777619)>>>0;return h.toString(16).padStart(8,'0');}
 function validLonLat(p){return Array.isArray(p)&&p.length>=2&&Number.isFinite(p[0])&&Number.isFinite(p[1])&&p[0]>=-180&&p[0]<=180&&p[1]>=-85.05&&p[1]<=85.05;}
 function bboxIntersects(a,b){return a[0]<=b[2]&&a[2]>=b[0]&&a[1]<=b[3]&&a[3]>=b[1];}
 function bboxPolygon(rings){let minx=Infinity,miny=Infinity,maxx=-Infinity,maxy=-Infinity,verts=0;
  for(const ring of rings){if(!Array.isArray(ring)||ring.length<4)throw Error('包含無效的多邊形環（至少需要四個座標點）');
   for(const p of ring){if(!validLonLat(p))throw Error('座標不是 WGS84 經緯度。請先用 QGIS 轉成 EPSG:4326 GeoJSON。');
    minx=Math.min(minx,p[0]);miny=Math.min(miny,p[1]);maxx=Math.max(maxx,p[0]);maxy=Math.max(maxy,p[1]);verts++;
   }
   const first=ring[0],last=ring[ring.length-1];if(Math.abs(first[0]-last[0])>1e-8||Math.abs(first[1]-last[1])>1e-8)throw Error('多邊形未閉合。請先修復 GeoJSON 幾何後再匯入。');
  }
  if(minx===maxx||miny===maxy)throw Error('發現零面積的地塊，請先修正來源資料。');
  return {bbox:[minx,miny,maxx,maxy],vertices:verts};
 }
 function inRing(point,ring){const x=point[0],y=point[1];let inside=false;
  for(let i=0,j=ring.length-1;i<ring.length;j=i++){
   const a=ring[i],b=ring[j];if(((a[1]>y)!==(b[1]>y))&&(x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]))inside=!inside;
  }return inside;
 }
 function inside(point,rings){let parity=false;for(const ring of rings){if(inRing(point,ring))parity=!parity;}return parity;}
 function findRepresentative(rings,b){let p=[(b[0]+b[2])/2,(b[1]+b[3])/2];if(inside(p,rings))return p;
  const first=rings[0],sum=first.reduce((a,p)=>[a[0]+p[0],a[1]+p[1]],[0,0]);p=[sum[0]/first.length,sum[1]/first.length];if(inside(p,rings))return p;
  const x=first[0],y=first[1],target=[(b[0]+b[2])/2,(b[1]+b[3])/2];return [x[0]*.999+target[0]*.001,x[1]*.999+target[1]*.001];
 }
 function prepare(text,year,name='F03.geojson'){
  if(year!==4&&year!==5)throw Error('只能指定民國111年或112年的 F03 資料');
  if(typeof text!=='string'||!text.trim())throw Error('GeoJSON 是空白檔案');
  if(new TextEncoder().encode(text).byteLength>MAX_BYTES)throw Error('檔案大於 60MB，請先按鄉鎮分割或簡化資料');
  let raw;try{raw=JSON.parse(text);}catch(e){throw Error('檔案不是有效的 GeoJSON JSON 格式');}
  if(raw?.type!=='FeatureCollection'||!Array.isArray(raw.features))throw Error('僅支援 FeatureCollection（Polygon／MultiPolygon）');
  const geomKinds=new Set(raw.features.map(f=>f?.geometry?.type||'無幾何'));
  if(geomKinds.size&&[...geomKinds].every(t=>t==='Point'||t==='MultiPoint'||t==='無幾何'))throw Error('這是豬場「點位標記 GeoJSON」，不是畜牧使用 F03「橘色地塊 GeoJSON」。請用豬場資料的「匯入資料」；橘色地塊請從 F03 擷取工作台匯出後再匯入。線上橘色圖層不會因此清除。');
  if(raw.__f03_acquisition && (raw.__f03_acquisition.status!=='complete' || Number(raw.__f03_acquisition.expectedCount)!==Number(raw.__f03_acquisition.downloadedCount)))throw Error('此檔的官方擷取紀錄顯示未完成或有缺筆，為避免誤認全區完整，請重新擷取成功後再匯入');
  if(raw.__f03_acquisition && Number(raw.__f03_acquisition.year)!==(year===4?112:111))throw Error('擷取資料的民國年度與目前選取年度不符');
  const crs=raw.crs?.properties?.name||raw.crs?.name||'';
  if(crs&&!/4326|crs84/i.test(crs))throw Error('來源 CRS 不是 EPSG:4326；請先重投影後再匯入');
  if(raw.features.length<1||raw.features.length>MAX_ITEMS)throw Error('地塊數必須介於 1 到 100,000 筆');
  const digest=hashText(text),features=[],cells=new Map(),wide=[];let totalVerts=0,extent=[Infinity,Infinity,-Infinity,-Infinity];
  function addIndex(f,index){const [x0,y0,x1,y1]=f.bbox,ix0=Math.floor(x0/BUCKET),ix1=Math.floor(x1/BUCKET),iy0=Math.floor(y0/BUCKET),iy1=Math.floor(y1/BUCKET);
   if((ix1-ix0+1)*(iy1-iy0+1)>180){wide.push(index);return;}
   for(let x=ix0;x<=ix1;x++)for(let y=iy0;y<=iy1;y++){const k=x+','+y;let a=cells.get(k);if(!a){a=[];cells.set(k,a);}a.push(index);}
  }
  for(let i=0;i<raw.features.length;i++){
   const row=raw.features[i],g=row?.geometry;const cls=row?.properties?.['盤查分類']??row?.properties?.['土地使用分類'];
   if(cls!=null&&String(cls).trim()&&!/(畜牧|F03|livestock)/i.test(String(cls)))throw Error('第 '+(i+1)+' 筆的盤查分類不是畜牧使用：'+String(cls).slice(0,40));
   if(row?.type!=='Feature'||!g||!['Polygon','MultiPolygon'].includes(g.type))throw Error('第 '+(i+1)+' 筆不是有效的 Polygon／MultiPolygon，已取消整次匯入');
   const parts=g.type==='Polygon'?[g.coordinates]:g.coordinates;
   if(!Array.isArray(parts)||!parts.length)throw Error('第 '+(i+1)+' 筆沒有有效地塊輪廓');
   for(let j=0;j<parts.length;j++){
    const rings=parts[j];if(!Array.isArray(rings)||!rings.length)throw Error('第 '+(i+1)+' 筆地塊內容不完整');
    const {bbox,vertices}=bboxPolygon(rings);extent=[Math.min(extent[0],bbox[0]),Math.min(extent[1],bbox[1]),Math.max(extent[2],bbox[2]),Math.max(extent[3],bbox[3])];totalVerts+=vertices;if(totalVerts>MAX_VERTICES)throw Error('座標頂點超過 320 萬個，請先按區域分檔');
    const key=`OFFLINE-${year}-${digest}-${i}-${j}`;
    const candidate={key,year,source:'offline',bbox,rings,center:findRepresentative(rings,bbox),objectId:row.properties?.OBJECTID??row.properties?.objectid??null};
    const idx=features.length;features.push(candidate);addIndex(candidate,idx);
   }
  }
  const meta={year,name:String(name).slice(0,120),hash:digest,count:features.length,featureCount:raw.features.length,vertices:totalVerts,extent,bytes:new TextEncoder().encode(text).byteLength,loadedAt:new Date().toISOString(),acquisition:raw.__f03_acquisition||null};
  return {meta,features,cells,wide,rawText:text};
 }
 function get(year){return datasets.get(year)||null;}
  function loadPackaged(text,year,name){const data=prepare(text,year,name);packaged.set(year,data);return data;}
  function getPackaged(year){return packaged.get(year)||null;}
  function getForMode(year,mode){return mode==='builtin'?getPackaged(year):get(year);}
 function activate(data){datasets.set(data.meta.year,data);META.set(data.meta.year,data.meta);return data;}
 function meta(year){return META.get(year)||null;}
 function candidatesForBounds(dataset,extent){if(!dataset)return [];
  const b=Array.isArray(extent)?extent:[extent.west,extent.south,extent.east,extent.north],ids=new Set(dataset.wide);
  const ix0=Math.floor(b[0]/BUCKET),ix1=Math.floor(b[2]/BUCKET),iy0=Math.floor(b[1]/BUCKET),iy1=Math.floor(b[3]/BUCKET);
  // Large viewport: return all potential parcels, never silently omit areas.
  if((ix1-ix0+1)*(iy1-iy0+1)>12000){return dataset.features.filter(f=>bboxIntersects(f.bbox,b));}
  for(let x=ix0;x<=ix1;x++)for(let y=iy0;y<=iy1;y++)for(const i of dataset.cells.get(x+','+y)||[])ids.add(i);
  return [...ids].map(i=>dataset.features[i]).filter(f=>bboxIntersects(f.bbox,b));
 }
 function at(year,lat,lng,mode='offline'){const dataset=getForMode(year,mode);if(!dataset)return null;
  const candidates=candidatesForBounds(dataset,[lng,lat,lng,lat]);return candidates.find(f=>inside([lng,lat],f.rings))||null;
 }
 function tileExtent(coords){const n=2**coords.z;
  function lng(x){return x/n*360-180;}
  function lat(y){return Math.atan(Math.sinh(Math.PI*(1-2*y/n)))*180/Math.PI;}
  return [lng(coords.x),lat(coords.y+1),lng(coords.x+1),lat(coords.y)];
 }
 function render(canvas,coords,year,mode='offline'){const dataset=getForMode(year,mode);if(!dataset)return 0;
  const ctx=canvas.getContext('2d'),sz=canvas.width,b=tileExtent(coords),items=candidatesForBounds(dataset,b);
  if(items.length>8000)throw Error('單格地塊超過 8,000 個，請放大再檢視，未略過任何地塊');
  const n=2**coords.z;
  ctx.save();ctx.beginPath();ctx.rect(0,0,sz,sz);ctx.clip();ctx.fillStyle='rgba(245,145,34,.82)';ctx.strokeStyle='rgba(175,83,19,.90)';ctx.lineWidth=.85;
  for(const f of items){ctx.beginPath();for(const ring of f.rings){for(let k=0;k<ring.length;k++){
   const lng=ring[k][0],lat=Math.max(-85.05112,Math.min(85.05112,ring[k][1]));
   const x=((lng+180)/360*n-coords.x)*sz;
   const y=((1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n-coords.y)*sz;
   if(k===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
  }ctx.closePath();}ctx.fill('evenodd');ctx.stroke();}
  ctx.restore();return items.length;
 }
 function openDb(){if(dbPromise)return dbPromise;if(typeof indexedDB==='undefined')return Promise.reject(Error('瀏覽器不支援 IndexedDB'));
  dbPromise=new Promise((resolve,reject)=>{let req;try{req=indexedDB.open(DB_NAME,1);}catch(e){reject(e);return;}
   req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(STORE))req.result.createObjectStore(STORE,{keyPath:'year'});};
   req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('開啟離線資料庫失敗'));
  }).catch(e=>{dbPromise=null;throw e;});return dbPromise;
 }
 async function stored(year){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readonly'),req=tx.objectStore(STORE).get(year);
  req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error||Error('讀取地塊資料庫失敗'));});}
 async function persist(data,file){const db=await openDb(),row={year:data.meta.year,meta:data.meta,file};
  await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(row);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('儲存圖資失敗'));tx.onabort=()=>reject(tx.error||Error('儲存已取消'));});
  const check=await stored(data.meta.year);if(check?.meta?.hash!==data.meta.hash||!check.file)throw Error('離線資料庫寫入後校驗失敗');
  return true;
 }
 async function restore(year){const row=await stored(year);if(!row){datasets.delete(year);META.delete(year);return null;}
  const text=await row.file.text(),data=prepare(text,year,row.meta?.name||row.file.name||'F03.geojson');
  if(data.meta.hash!==row.meta.hash)throw Error('離線 F03 資料內容校驗不符，請重新匯入');
  activate(data);return data;
 }
 async function forget(year){const db=await openDb();await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).delete(year);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('移除失敗'));tx.onabort=()=>reject(tx.error||Error('移除取消'));});
  datasets.delete(year);META.delete(year);
 }
 return {prepare,activate,get,meta,at,inside,render,tileExtent,candidatesForBounds,openDb,restore,persist,forget,MAX_BYTES,loadPackaged,getPackaged,getForMode};
})();

